import 'package:flutter/material.dart';import '../../Features/Splash/Pages/splash_screen.dart';import '../../Features/Authentication/presentation/pages/authentication_screen.dart';import '../../Features/Main/presentation/pages/main_screen.dart';import 'route_name.dart';class AppRoutes {  static Route<dynamic> generateRoute(RouteSettings settings) {    switch (settings.name) {      case AppRouteNames.splash:        return MaterialPageRoute(builder: (_) => const SplashScreen());      case AppRouteNames.home:        return MaterialPageRoute(builder: (_) => const MainScreen());      case AppRouteNames.start:        return MaterialPageRoute(builder: (_) => const AuthenticationScreen());      default:        return MaterialPageRoute(          builder: (_) => Scaffold(            body: Center(              child: Text('No route defined for "${settings.name?.split("/").last}" '),            ),          ),        );    }  }}